-- specs/03_schema.sql
-- Concatenation of migrations/0001..0008 in apply order (generated by the build; do not edit here).
-- Applied migrations are verified by SHA-256 in schema_migrations.

-- ===== 0001_provenance.sql =====
-- 0001_provenance.sql
-- Provenance tables for obj1_master (database/kambale_thesis.sqlite).
-- Every raw-to-curated derivation is traceable through these tables.

CREATE TABLE source_files (
    source_file_id   INTEGER PRIMARY KEY,
    file_name        TEXT    NOT NULL,
    original_path    TEXT    NOT NULL,           -- path as supplied, recorded for audit
    raw_copy_path    TEXT    NOT NULL,           -- immutable copy under data/raw/
    sha256           TEXT    NOT NULL UNIQUE CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
    size_bytes       INTEGER NOT NULL CHECK (size_bytes > 0),
    first_seen_utc   TEXT    NOT NULL,
    notes            TEXT
);

CREATE TABLE source_sheets (
    source_sheet_id     INTEGER PRIMARY KEY,
    source_file_id      INTEGER NOT NULL REFERENCES source_files (source_file_id),
    sheet_name          TEXT    NOT NULL,
    sheet_state         TEXT    NOT NULL CHECK (sheet_state IN ('visible', 'hidden', 'veryHidden')),
    n_rows              INTEGER NOT NULL CHECK (n_rows >= 0),
    n_cols              INTEGER NOT NULL CHECK (n_cols >= 0),
    header_json         TEXT,                   -- JSON array of header strings as stored in the workbook
    blank_columns_json  TEXT,                   -- JSON array of header names whose data cells are all blank
    UNIQUE (source_file_id, sheet_name)
);

CREATE TABLE ingestion_runs (
    ingestion_run_id     INTEGER PRIMARY KEY,
    source_file_id       INTEGER NOT NULL REFERENCES source_files (source_file_id),
    started_utc          TEXT    NOT NULL,
    finished_utc         TEXT,
    etl_version          TEXT    NOT NULL,
    dataset_version_key  TEXT,
    status               TEXT    NOT NULL CHECK (status IN ('RUNNING', 'VERIFIED', 'NOOP_IDENTICAL', 'FAILED')),
    message              TEXT
);

CREATE TABLE dataset_versions (
    dataset_version_id       INTEGER PRIMARY KEY,
    dataset_version_key      TEXT    NOT NULL UNIQUE,
    dataset_label            TEXT    NOT NULL,
    source_file_id           INTEGER NOT NULL REFERENCES source_files (source_file_id),
    etl_version              TEXT    NOT NULL,
    rule_versions_json       TEXT    NOT NULL,
    coordinate_decision_json TEXT    NOT NULL,
    status                   TEXT    NOT NULL CHECK (status IN ('BUILDING', 'ACTIVE', 'ARCHIVED', 'FAILED')),
    overall_status           TEXT    CHECK (overall_status IN ('VERIFIED', 'PROVISIONAL', 'BLOCKED', 'DEFERRED', 'FAILED')),
    created_utc              TEXT    NOT NULL,
    activated_utc            TEXT,
    archived_utc             TEXT
);

-- Exactly one ACTIVE dataset version may exist at any time.
CREATE UNIQUE INDEX ux_dataset_versions_one_active
    ON dataset_versions (status) WHERE status = 'ACTIVE';

CREATE TABLE raw_row_map (
    raw_row_map_id   INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL,
    source_row       INTEGER NOT NULL CHECK (source_row >= 1),   -- 1-based Excel row number
    raw_table        TEXT    NOT NULL,
    raw_rowid        INTEGER NOT NULL,
    UNIQUE (source_file_id, source_sheet, source_row)
);

CREATE TABLE analysis_runs (
    analysis_run_id   INTEGER PRIMARY KEY,
    command           TEXT    NOT NULL,
    args_json         TEXT    NOT NULL,
    code_version      TEXT    NOT NULL,
    dataset_version_id INTEGER REFERENCES dataset_versions (dataset_version_id),
    started_utc       TEXT    NOT NULL,
    finished_utc      TEXT,
    status            TEXT    NOT NULL CHECK (status IN ('RUNNING', 'VERIFIED', 'FAILED', 'BLOCKED')),
    message           TEXT
);

-- ===== 0002_raw.sql =====
-- 0002_raw.sql
-- Immutable raw copies of workbook rows. Column names match the workbook headers exactly.
-- No declared column types: SQLite stores each value as read (no affinity coercion).
-- UPDATE and DELETE are rejected by triggers so source rows are never overwritten.

CREATE TABLE raw_collars (
    raw_collars_id   INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL DEFAULT 'Collars',
    source_row       INTEGER NOT NULL CHECK (source_row >= 2),
    HoleID,
    Grid,
    HoleType,
    Northing,
    Easting,
    RL,
    UTMNorthing,
    UTMEasting,
    max_depth,
    Project,
    Prospect,
    Contractor,
    LoggedBy,
    DateDrilled,
    payload_json    TEXT    NOT NULL,
    UNIQUE (source_file_id, source_sheet, source_row)
);

CREATE TABLE raw_surveys (
    raw_surveys_id   INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL DEFAULT 'Surveys',
    source_row       INTEGER NOT NULL CHECK (source_row >= 2),
    HoleID,
    depth,
    dip,
    azimuth,
    SurveyedBy,
    Instrument,
    payload_json    TEXT    NOT NULL,
    UNIQUE (source_file_id, source_sheet, source_row)
);

CREATE TABLE raw_logging (
    raw_logging_id   INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL DEFAULT 'Logging',
    source_row       INTEGER NOT NULL CHECK (source_row >= 2),
    HOLEID,
    DEPTH_FROM,
    DEPTH_TO,
    rock_type1,
    colour1,
    colour2,
    weathering,
    grainsize,
    structure,
    alt_min1,
    alt_min1int,
    alt_min2,
    alt_min2int,
    sul_min1,
    sul_min1pc,
    vn_type,
    vn_pc,
    Comment,
    sample_quality,
    payload_json    TEXT    NOT NULL,
    UNIQUE (source_file_id, source_sheet, source_row)
);

CREATE TABLE raw_geological_legend (
    raw_legend_id    INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL DEFAULT 'Logging Legend',
    source_row       INTEGER NOT NULL CHECK (source_row >= 1),
    legend_reference,
    legend_value,
    description,
    payload_json     TEXT    NOT NULL,
    UNIQUE (source_file_id, source_sheet, source_row)
);

-- Hidden reference sheets (___LoggingReferences, ___SurveyReferences, ___CollarReferences, ___SheetInfo).
-- Values are stored one row per (sheet, column, ordinal). The ___SheetInfo worksheet-protection value
-- is redacted in this copy; the original workbook bytes are unchanged and hashed in source_files.
CREATE TABLE raw_reference_lists (
    raw_reference_id INTEGER PRIMARY KEY,
    source_file_id   INTEGER NOT NULL REFERENCES source_files (source_file_id),
    source_sheet     TEXT    NOT NULL,
    source_row       INTEGER NOT NULL CHECK (source_row >= 1),
    column_name      TEXT    NOT NULL,
    ordinal          INTEGER NOT NULL CHECK (ordinal >= 1),
    value            TEXT,
    redacted         INTEGER NOT NULL DEFAULT 0 CHECK (redacted IN (0, 1)),
    UNIQUE (source_file_id, source_sheet, column_name, ordinal)
);

CREATE TRIGGER raw_collars_no_update BEFORE UPDATE ON raw_collars
BEGIN SELECT RAISE(ABORT, 'raw_collars is immutable'); END;
CREATE TRIGGER raw_collars_no_delete BEFORE DELETE ON raw_collars
BEGIN SELECT RAISE(ABORT, 'raw_collars is immutable'); END;

CREATE TRIGGER raw_surveys_no_update BEFORE UPDATE ON raw_surveys
BEGIN SELECT RAISE(ABORT, 'raw_surveys is immutable'); END;
CREATE TRIGGER raw_surveys_no_delete BEFORE DELETE ON raw_surveys
BEGIN SELECT RAISE(ABORT, 'raw_surveys is immutable'); END;

CREATE TRIGGER raw_logging_no_update BEFORE UPDATE ON raw_logging
BEGIN SELECT RAISE(ABORT, 'raw_logging is immutable'); END;
CREATE TRIGGER raw_logging_no_delete BEFORE DELETE ON raw_logging
BEGIN SELECT RAISE(ABORT, 'raw_logging is immutable'); END;

CREATE TRIGGER raw_legend_no_update BEFORE UPDATE ON raw_geological_legend
BEGIN SELECT RAISE(ABORT, 'raw_geological_legend is immutable'); END;
CREATE TRIGGER raw_legend_no_delete BEFORE DELETE ON raw_geological_legend
BEGIN SELECT RAISE(ABORT, 'raw_geological_legend is immutable'); END;

CREATE TRIGGER raw_reference_no_update BEFORE UPDATE ON raw_reference_lists
BEGIN SELECT RAISE(ABORT, 'raw_reference_lists is immutable'); END;
CREATE TRIGGER raw_reference_no_delete BEFORE DELETE ON raw_reference_lists
BEGIN SELECT RAISE(ABORT, 'raw_reference_lists is immutable'); END;

-- ===== 0003_curated_core.sql =====
-- 0003_curated_core.sql
-- Curated, version-scoped records. Every row carries dataset_version_id and a link to its raw row.
-- Holes, surveys and intervals are keyed by the normalised hole_id; raw spellings are kept.

CREATE TABLE drill_lines (
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    line_code               TEXT    NOT NULL,                 -- e.g. NOM_N1112140 (nominal Northing)
    nominal_northing_m      REAL    NOT NULL,
    n_holes                 INTEGER NOT NULL CHECK (n_holes > 0),
    n_intervals             INTEGER NOT NULL CHECK (n_intervals >= 0),
    grouping_method         TEXT    NOT NULL,
    status                  TEXT    NOT NULL CHECK (status IN ('PROVISIONAL', 'APPROVED')),
    PRIMARY KEY (dataset_version_id, line_code)
);

CREATE TABLE holes (
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    hole_id                 TEXT    NOT NULL,                 -- normalised identifier
    raw_hole_id             TEXT    NOT NULL,                 -- as stored in the workbook
    raw_collars_id          INTEGER NOT NULL REFERENCES raw_collars (raw_collars_id),
    hole_type               TEXT    NOT NULL,
    grid_label              TEXT    NOT NULL,                 -- grid nickname as recorded (e.g. UTM_30N)
    easting_alt_m           REAL,                             -- Easting column (alternate pair)
    northing_alt_m          REAL,                             -- Northing column (alternate pair)
    utm_easting_m           REAL,                             -- UTMEasting column
    utm_northing_m          REAL,                             -- UTMNorthing column
    line_code               TEXT,
    rl_status               TEXT    NOT NULL CHECK (rl_status IN ('MISSING', 'PRESENT')),
    rl_m                    REAL    CHECK (rl_m IS NULL OR rl_status = 'PRESENT'),
    max_depth_m             REAL    NOT NULL CHECK (max_depth_m > 0),
    project_code            TEXT,
    prospect                TEXT,
    contractor              TEXT,                             -- NULL when blank
    logged_by               TEXT,
    date_drilled            TEXT    CHECK (date_drilled IS NULL OR date_drilled GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    date_drilled_raw        TEXT,
    PRIMARY KEY (dataset_version_id, hole_id),
    FOREIGN KEY (dataset_version_id, line_code) REFERENCES drill_lines (dataset_version_id, line_code)
);

CREATE TABLE survey_stations (
    survey_station_id       INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    hole_id                 TEXT    NOT NULL,
    raw_surveys_id          INTEGER NOT NULL REFERENCES raw_surveys (raw_surveys_id),
    depth_m                 REAL    NOT NULL CHECK (depth_m > 0),
    dip_deg                 REAL    NOT NULL CHECK (dip_deg >= -90 AND dip_deg <= 0),   -- from horizontal, negative downward
    azimuth_deg             REAL    NOT NULL CHECK (azimuth_deg >= 0 AND azimuth_deg < 360),
    station_kind            TEXT    NOT NULL CHECK (station_kind IN ('END_OF_HOLE_ONLY', 'MULTI_STATION', 'SINGLE_STATION_OTHER')),
    surveyed_by             TEXT,                             -- NULL = MISSING in source
    instrument              TEXT,                             -- NULL = MISSING in source
    convention_status       TEXT    NOT NULL CHECK (convention_status IN ('PROVISIONAL', 'APPROVED')),
    UNIQUE (dataset_version_id, hole_id, depth_m),
    FOREIGN KEY (dataset_version_id, hole_id) REFERENCES holes (dataset_version_id, hole_id)
);

CREATE TABLE geological_code_dictionary (
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    code_domain             TEXT    NOT NULL CHECK (code_domain IN
                              ('RockType', 'Colour', 'Weathering', 'Structure', 'RTMineral', 'SulMineral', 'Veining', 'SampleQual')),
    code                    TEXT    NOT NULL,
    description             TEXT    NOT NULL,
    legend_source_row       INTEGER,
    in_logging_legend       INTEGER NOT NULL CHECK (in_logging_legend IN (0, 1)),
    in_hidden_reference     INTEGER NOT NULL CHECK (in_hidden_reference IN (0, 1)),
    PRIMARY KEY (dataset_version_id, code_domain, code)
);

CREATE TABLE logging_intervals (
    interval_id             INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    interval_key            TEXT    NOT NULL,                 -- stable across versions: hole_id@from
    hole_id                 TEXT    NOT NULL,
    raw_logging_id          INTEGER NOT NULL REFERENCES raw_logging (raw_logging_id),
    source_row              INTEGER NOT NULL,
    depth_from_m            REAL    NOT NULL CHECK (depth_from_m >= 0),
    depth_to_m              REAL    NOT NULL CHECK (depth_to_m > depth_from_m),
    interval_length_m       REAL    NOT NULL CHECK (interval_length_m > 0),
    midpoint_m              REAL    NOT NULL CHECK (midpoint_m > 0),
    rock_code_raw           TEXT,
    rock_code_status        TEXT    NOT NULL CHECK (rock_code_status IN ('VALID', 'UNSUPPORTED', 'MISSING')),
    rock_description        TEXT,
    colour1_code            TEXT,
    colour2_code            TEXT,
    weathering_code         TEXT,
    weathering_status       TEXT    NOT NULL CHECK (weathering_status IN ('VALID', 'MISSING', 'UNSUPPORTED')),
    grainsize_raw           REAL,
    structure_code          TEXT,
    alt_min1_code           TEXT,
    alt_min1_int            REAL,
    alt_min2_code           TEXT,
    alt_min2_int            REAL,
    sul_min1_code           TEXT,
    sul_min1_pc             REAL,
    vn_type                 TEXT,
    vn_pc                   REAL,
    comment_raw             TEXT,
    sample_quality_code     TEXT,
    UNIQUE (dataset_version_id, interval_key),
    UNIQUE (dataset_version_id, hole_id, depth_from_m),
    FOREIGN KEY (dataset_version_id, hole_id) REFERENCES holes (dataset_version_id, hole_id)
);

CREATE INDEX ix_logging_intervals_hole ON logging_intervals (dataset_version_id, hole_id);
CREATE INDEX ix_survey_stations_hole ON survey_stations (dataset_version_id, hole_id);

-- ===== 0004_labels.sql =====
-- 0004_labels.sql
-- Graphitic label candidates. Evidence fields are logged indicators, not independent laboratory tests.
-- No rule is APPROVED without a recorded reviewer decision (enforced by trigger below).

CREATE TABLE graphite_label_rules (
    rule_id                 TEXT    PRIMARY KEY,              -- e.g. STRICT_SGS_v1
    rule_version            TEXT    NOT NULL,
    rule_family             TEXT    NOT NULL CHECK (rule_family IN ('STRICT', 'RECONCILED', 'SENSITIVITY')),
    description             TEXT    NOT NULL,
    definition_sha256       TEXT    NOT NULL,                 -- hash of the YAML definition used
    status                  TEXT    NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED', 'APPROVED', 'REJECTED')),
    approved_by             TEXT,
    approved_utc            TEXT,
    created_utc             TEXT    NOT NULL,
    CHECK (status <> 'APPROVED' OR (approved_by IS NOT NULL AND approved_utc IS NOT NULL))
);

CREATE TABLE label_reviews (
    label_review_id         INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER REFERENCES dataset_versions (dataset_version_id),
    rule_id                 TEXT    NOT NULL REFERENCES graphite_label_rules (rule_id),
    scope                   TEXT    NOT NULL CHECK (scope IN ('RULE', 'INTERVAL', 'HOLE', 'EVIDENCE_PATTERN')),
    scope_key               TEXT,
    reviewer                TEXT    NOT NULL,
    decision                TEXT    NOT NULL CHECK (decision IN
                              ('APPROVE_RULE', 'REJECT_RULE', 'AMEND_RULE', 'ACCEPT_LABEL', 'OVERRIDE_LABEL', 'DEFER')),
    decided_utc             TEXT    NOT NULL,
    rationale               TEXT    NOT NULL
);

-- FR-010: a rule may become APPROVED only when an APPROVE_RULE review exists for it.
CREATE TRIGGER graphite_rule_approval_requires_review
BEFORE UPDATE OF status ON graphite_label_rules
WHEN NEW.status = 'APPROVED'
     AND NOT EXISTS (SELECT 1 FROM label_reviews r WHERE r.rule_id = NEW.rule_id AND r.decision = 'APPROVE_RULE')
BEGIN
    SELECT RAISE(ABORT, 'graphite rule cannot be APPROVED without an APPROVE_RULE label_reviews row');
END;

CREATE TABLE interval_label_evidence (
    dataset_version_id          INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    interval_id                 INTEGER NOT NULL REFERENCES logging_intervals (interval_id),
    rock_code_status            TEXT    NOT NULL CHECK (rock_code_status IN ('VALID', 'UNSUPPORTED', 'MISSING')),
    is_sgs                      INTEGER CHECK (is_sgs IS NULL OR is_sgs IN (0, 1)),          -- NULL unless rock code VALID
    has_gr_mineral              INTEGER NOT NULL CHECK (has_gr_mineral IN (0, 1)),          -- alt_min1 or alt_min2 == 'gr'
    comment_present             INTEGER NOT NULL CHECK (comment_present IN (0, 1)),
    comment_graphitic           INTEGER NOT NULL CHECK (comment_graphitic IN (0, 1)),       -- regex 'graphit' (case-insensitive)
    comment_trace_qualified     INTEGER NOT NULL CHECK (comment_trace_qualified IN (0, 1)), -- 'trace' and 'graphit' both present
    comment_term                TEXT    CHECK (comment_term IS NULL OR comment_term IN ('graphitic', 'graphite')),
    positive_indicators         INTEGER NOT NULL CHECK (positive_indicators BETWEEN 0 AND 3),
    negative_indicators         INTEGER NOT NULL CHECK (negative_indicators BETWEEN 0 AND 3),
    label_conflict              INTEGER NOT NULL CHECK (label_conflict IN (0, 1)),
    evidence_pattern            TEXT    NOT NULL,            -- e.g. SGS+GR+CMT, SGS+CMT, CMT, NONE
    label_review_status         TEXT    NOT NULL CHECK (label_review_status IN
                                  ('CONSISTENT_POSITIVE', 'CONSISTENT_NEGATIVE', 'CONFLICT_REVIEW_REQUIRED',
                                   'UNRESOLVED_CODE', 'UNRESOLVED_NO_COMMENT', 'UNRESOLVED_PARTIAL_EVIDENCE')),
    rationale                   TEXT    NOT NULL,
    PRIMARY KEY (dataset_version_id, interval_id)
);

CREATE TABLE interval_labels (
    dataset_version_id          INTEGER NOT NULL,
    interval_id                 INTEGER NOT NULL,
    rule_id                     TEXT    NOT NULL REFERENCES graphite_label_rules (rule_id),
    label                       INTEGER CHECK (label IS NULL OR label IN (0, 1)),
    label_state                 TEXT    NOT NULL CHECK (label_state IN ('POSITIVE', 'NEGATIVE', 'UNRESOLVED')),
    rule_status_at_derivation   TEXT    NOT NULL,
    PRIMARY KEY (dataset_version_id, interval_id, rule_id),
    FOREIGN KEY (dataset_version_id, interval_id)
        REFERENCES interval_label_evidence (dataset_version_id, interval_id),
    CHECK ((label_state = 'POSITIVE' AND label = 1) OR (label_state = 'NEGATIVE' AND label = 0)
           OR (label_state = 'UNRESOLVED' AND label IS NULL))
);

CREATE INDEX ix_interval_labels_rule ON interval_labels (rule_id, dataset_version_id, label_state);

-- ===== 0005_geometry.sql =====
-- 0005_geometry.sql
-- Coordinate decisions, elevation status and versioned straight-hole geometry.
-- Absolute elevation is blocked by construction: interval_coordinates.z_absolute_m must be NULL.
-- A later migration may relax the CHECK only after an APPROVED elevation source is recorded.

CREATE TABLE coordinate_system_registry (
    crs_key                 TEXT    PRIMARY KEY,              -- e.g. EPSG:32630
    authority_code          TEXT    NOT NULL,
    crs_name                TEXT    NOT NULL,
    projection              TEXT    NOT NULL,
    zone                    TEXT,
    datum_name              TEXT,
    datum_status            TEXT    NOT NULL CHECK (datum_status IN ('VERIFIED', 'UNVERIFIED')),
    horizontal_units        TEXT    NOT NULL CHECK (horizontal_units = 'm'),
    evidence                TEXT    NOT NULL,
    status                  TEXT    NOT NULL CHECK (status IN ('PROVISIONAL', 'APPROVED', 'BLOCKED'))
);

CREATE TABLE coordinate_decisions (
    coordinate_decision_id          INTEGER PRIMARY KEY,
    dataset_version_id              INTEGER NOT NULL UNIQUE REFERENCES dataset_versions (dataset_version_id),
    adopted_pair                    TEXT    NOT NULL CHECK (adopted_pair IN ('UTM_EASTING_NORTHING', 'EASTING_NORTHING')),
    crs_key                         TEXT    NOT NULL REFERENCES coordinate_system_registry (crs_key),
    units                           TEXT    NOT NULL CHECK (units = 'm'),
    transform_chain                 TEXT    NOT NULL,
    rationale                       TEXT    NOT NULL,
    n_holes                         INTEGER NOT NULL CHECK (n_holes > 0),
    median_pair_discrepancy_m       REAL    NOT NULL CHECK (median_pair_discrepancy_m >= 0),
    max_pair_discrepancy_m          REAL    NOT NULL CHECK (max_pair_discrepancy_m >= median_pair_discrepancy_m),
    status                          TEXT    NOT NULL CHECK (status IN ('PROVISIONAL', 'APPROVED')),
    approved_by                     TEXT,
    approved_utc                    TEXT
);

CREATE TABLE elevation_sources (
    elevation_source_id     INTEGER PRIMARY KEY,
    source_type             TEXT    NOT NULL CHECK (source_type IN ('NONE', 'DGPS_SURVEY', 'DEM', 'OTHER')),
    description             TEXT    NOT NULL,
    vertical_datum          TEXT,
    status                  TEXT    NOT NULL CHECK (status IN ('BLOCKED', 'PROVISIONAL', 'APPROVED')),
    approved_by             TEXT,
    approved_utc            TEXT,
    CHECK (status <> 'APPROVED' OR (vertical_datum IS NOT NULL AND approved_by IS NOT NULL))
);

INSERT INTO elevation_sources (elevation_source_id, source_type, description, vertical_datum, status)
VALUES (1, 'NONE',
        'No collar RL in workbook (RL blank for all collars); no DGPS survey or DEM supplied. Absolute elevation BLOCKED.',
        NULL, 'BLOCKED');

CREATE TABLE geometry_builds (
    geometry_build_id       INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    coordinate_decision_id  INTEGER NOT NULL REFERENCES coordinate_decisions (coordinate_decision_id),
    elevation_source_id     INTEGER NOT NULL REFERENCES elevation_sources (elevation_source_id),
    method                  TEXT    NOT NULL CHECK (method = 'STRAIGHT_HOLE_EOH_ORIENTATION'),
    convention_text         TEXT    NOT NULL,
    angle_status            TEXT    NOT NULL CHECK (angle_status IN ('PROVISIONAL', 'APPROVED')),
    geometry_status         TEXT    NOT NULL CHECK (geometry_status IN ('PROVISIONAL_RELATIVE', 'BLOCKED_ABSOLUTE')),
    n_intervals             INTEGER NOT NULL CHECK (n_intervals >= 0),
    created_utc             TEXT    NOT NULL,
    UNIQUE (dataset_version_id, method)
);

CREATE TABLE interval_coordinates (
    geometry_build_id       INTEGER NOT NULL REFERENCES geometry_builds (geometry_build_id),
    interval_id             INTEGER NOT NULL REFERENCES logging_intervals (interval_id),
    midpoint_m              REAL    NOT NULL CHECK (midpoint_m > 0),
    dip_deg                 REAL    NOT NULL CHECK (dip_deg >= -90 AND dip_deg <= 0),
    azimuth_deg             REAL    NOT NULL CHECK (azimuth_deg >= 0 AND azimuth_deg < 360),
    delta_e_m               REAL    NOT NULL,
    delta_n_m               REAL    NOT NULL,
    delta_z_m               REAL    NOT NULL,
    easting_m               REAL    NOT NULL,
    northing_m              REAL    NOT NULL,
    z_relative_m            REAL    NOT NULL,                  -- relative to collar; NOT an elevation
    z_reference             TEXT    NOT NULL CHECK (z_reference = 'RELATIVE_TO_COLLAR'),
    z_absolute_m            REAL    CHECK (z_absolute_m IS NULL),  -- kept NULL until an APPROVED elevation source exists
    elevation_source_id     INTEGER NOT NULL REFERENCES elevation_sources (elevation_source_id),
    PRIMARY KEY (geometry_build_id, interval_id)
);

CREATE INDEX ix_interval_coordinates_build ON interval_coordinates (geometry_build_id);

-- ===== 0006_qaqc_audit.sql =====
-- 0006_qaqc_audit.sql
-- QA/QC catalogue and findings, figure and table registries, test evidence, export receipts,
-- and the regional geology context used as map background only.

CREATE TABLE qaqc_checks (
    check_id                TEXT    PRIMARY KEY,
    category                TEXT    NOT NULL,
    description             TEXT    NOT NULL,
    default_severity        TEXT    NOT NULL CHECK (default_severity IN ('ERROR', 'WARNING', 'INFO')),
    scope_if_failed         TEXT    NOT NULL,                 -- what is blocked or qualified when the check fails
    method                  TEXT    NOT NULL
);

CREATE TABLE qaqc_findings (
    finding_id              INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    check_id                TEXT    NOT NULL REFERENCES qaqc_checks (check_id),
    severity                TEXT    NOT NULL CHECK (severity IN ('ERROR', 'WARNING', 'INFO')),
    status                  TEXT    NOT NULL CHECK (status IN ('BLOCKED', 'PROVISIONAL', 'APPROVED')),
    result                  TEXT    NOT NULL CHECK (result IN ('PASS', 'FAIL')),
    entity_type             TEXT    NOT NULL CHECK (entity_type IN
                              ('DATASET', 'SHEET', 'HOLE', 'INTERVAL', 'CODE', 'COLUMN', 'SURVEY', 'LINE', 'COORDINATE')),
    entity_key              TEXT    NOT NULL DEFAULT '',
    source_sheet            TEXT,
    source_row              INTEGER,
    n_records               INTEGER NOT NULL DEFAULT 0 CHECK (n_records >= 0),
    detail                  TEXT    NOT NULL,
    UNIQUE (dataset_version_id, check_id, entity_type, entity_key)
);

CREATE TABLE qaqc_resolutions (
    resolution_id           INTEGER PRIMARY KEY,
    finding_id              INTEGER NOT NULL REFERENCES qaqc_findings (finding_id),
    action                  TEXT    NOT NULL CHECK (action IN
                              ('RETAINED_RAW', 'QUARANTINED', 'NULL_LABEL_UNRESOLVED', 'PROVISIONAL_GEOMETRY',
                               'NO_ACTION_REQUIRED', 'REVIEW_REQUIRED')),
    decided_by              TEXT    NOT NULL,
    decided_utc             TEXT    NOT NULL,
    rationale               TEXT    NOT NULL
);

CREATE TABLE figure_registry (
    figure_id               TEXT    PRIMARY KEY,              -- F01..F09, T01..T03
    objective               TEXT    NOT NULL CHECK (objective IN ('O1', 'O2', 'O3', 'O4', 'O5')),
    kind                    TEXT    NOT NULL CHECK (kind IN ('FIGURE', 'TABLE')),
    title                   TEXT    NOT NULL,
    caption                 TEXT    NOT NULL,
    stage_status            TEXT    NOT NULL CHECK (stage_status IN ('VERIFIED', 'PROVISIONAL', 'BLOCKED', 'DEFERRED', 'FAILED')),
    geometry_status         TEXT    NOT NULL,
    label_status            TEXT    NOT NULL,
    denominator             TEXT    NOT NULL,
    sql_file                TEXT    NOT NULL,
    renderer                TEXT    NOT NULL,
    created_utc             TEXT    NOT NULL
);

CREATE TABLE figure_query_registry (
    figure_query_id         INTEGER PRIMARY KEY,
    figure_id               TEXT    NOT NULL REFERENCES figure_registry (figure_id),
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    sql_file                TEXT    NOT NULL,
    sql_sha256              TEXT    NOT NULL,
    row_count               INTEGER NOT NULL CHECK (row_count >= 0),
    query_run_utc           TEXT    NOT NULL,
    analysis_run_id         INTEGER REFERENCES analysis_runs (analysis_run_id),
    UNIQUE (figure_id, dataset_version_id, sql_sha256, analysis_run_id)
);

CREATE TABLE figure_export_manifest (
    export_id               INTEGER PRIMARY KEY,
    figure_id               TEXT    NOT NULL REFERENCES figure_registry (figure_id),
    output_path             TEXT    NOT NULL,
    output_format           TEXT    NOT NULL CHECK (output_format IN ('SVG', 'PDF', 'PNG', 'CSV', 'MD', 'TEX', 'HTML')),
    output_sha256           TEXT    NOT NULL,
    output_bytes            INTEGER NOT NULL CHECK (output_bytes > 0),
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    figure_query_id         INTEGER REFERENCES figure_query_registry (figure_query_id),
    renderer_sha256         TEXT    NOT NULL,
    exported_utc            TEXT    NOT NULL,
    UNIQUE (figure_id, output_path)
);

-- Declared for completeness of the Stage A contract. Stage A writes no snapshots (views are used instead).
CREATE TABLE plot_statistic_snapshots (
    snapshot_id             INTEGER PRIMARY KEY,
    figure_id               TEXT    NOT NULL REFERENCES figure_registry (figure_id),
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    statistic_name          TEXT    NOT NULL,
    statistic_value         REAL,
    denominator             INTEGER,
    created_utc             TEXT    NOT NULL
);

CREATE TABLE validation_test_results (
    test_result_id          INTEGER PRIMARY KEY,
    run_utc                 TEXT    NOT NULL,
    dataset_version_id      INTEGER REFERENCES dataset_versions (dataset_version_id),
    test_group              TEXT    NOT NULL CHECK (test_group IN ('SQL_INTEGRITY', 'RECONCILIATION', 'PYTEST', 'FIGURE_PROVENANCE')),
    test_name               TEXT    NOT NULL,
    expected                TEXT    NOT NULL,
    observed                TEXT    NOT NULL,
    outcome                 TEXT    NOT NULL CHECK (outcome IN ('PASS', 'FAIL', 'WARN', 'NOT_RUN')),
    detail                  TEXT
);

CREATE TABLE dataset_export_receipts (
    receipt_id              INTEGER PRIMARY KEY,
    dataset_version_id      INTEGER NOT NULL REFERENCES dataset_versions (dataset_version_id),
    canonical_dataset_id    TEXT    NOT NULL,                 -- obj1_master:<dataset_version_key prefix>
    source_workbook_sha256  TEXT    NOT NULL,
    label_rule_id          TEXT    REFERENCES graphite_label_rules (rule_id),   -- NULL for exports that carry no label
    label_rule_status       TEXT,
    geometry_build_id       INTEGER REFERENCES geometry_builds (geometry_build_id),
    crs_key                 TEXT    NOT NULL,
    vertical_datum_status   TEXT    NOT NULL,
    export_name             TEXT    NOT NULL,
    selected_sql_sha256     TEXT    NOT NULL,
    row_count               INTEGER NOT NULL CHECK (row_count >= 0),
    ordered_id_digest       TEXT    NOT NULL,                 -- sha256 over ordered interval_key values
    status                  TEXT    NOT NULL CHECK (status IN ('VERIFIED', 'PROVISIONAL', 'BLOCKED', 'DEFERRED', 'FAILED')),
    exported_utc            TEXT    NOT NULL,
    UNIQUE (dataset_version_id, export_name, selected_sql_sha256)
);

-- Regional 1:1,000,000 geology polygons intersecting a buffer around the collars. Context only.
CREATE TABLE regional_geology_context (
    regional_polygon_id     INTEGER PRIMARY KEY,
    source_sha256           TEXT    NOT NULL,
    feature_index           INTEGER NOT NULL CHECK (feature_index >= 0),
    geo_symbol              TEXT    NOT NULL,
    stratigraphy            TEXT,
    legend_text             TEXT,
    metamorphism            TEXT,
    geom_wkt                TEXT    NOT NULL,
    centroid_e_m            REAL    NOT NULL,
    centroid_n_m            REAL    NOT NULL,
    intersects_collar_buffer INTEGER NOT NULL CHECK (intersects_collar_buffer IN (0, 1)),
    scale_note              TEXT    NOT NULL,
    UNIQUE (source_sha256, feature_index)
);

-- ===== 0007_future_contracts.sql =====
-- 0007_future_contracts.sql
-- Future-stage contracts (Stage B and Objectives 2-5). These tables exist only so that the schema
-- contract is explicit. They are EMPTY in obj1_master and every INSERT is rejected by a trigger.
-- Populated outputs belong to database/kambale_obj2_spatial.sqlite ... kambale_obj5_uncertainty.sqlite.

CREATE TABLE spatial_folds (
    fold_id                 INTEGER PRIMARY KEY,
    split_plan_id           TEXT    NOT NULL,
    fold_label              TEXT    NOT NULL,
    held_out_group          TEXT    NOT NULL,
    role                    TEXT    NOT NULL CHECK (role IN ('OUTER_TEST', 'TRAIN'))
);

CREATE TABLE variogram_runs (
    variogram_run_id        INTEGER PRIMARY KEY,
    scope                   TEXT    NOT NULL CHECK (scope IN ('EXPLORATORY_ALL_HOLES', 'TRAINING_ONLY')),
    status                  TEXT    NOT NULL CHECK (status IN ('DEFERRED', 'PROVISIONAL', 'APPROVED', 'REJECTED', 'NOT_IDENTIFIABLE'))
);

CREATE TABLE variogram_points (
    variogram_point_id      INTEGER PRIMARY KEY,
    variogram_run_id        INTEGER NOT NULL REFERENCES variogram_runs (variogram_run_id),
    lag_m                   REAL    NOT NULL,
    gamma                   REAL    NOT NULL,
    pair_count              INTEGER NOT NULL
);

CREATE TABLE model_runs (
    model_run_id            INTEGER PRIMARY KEY,
    model_family            TEXT    NOT NULL CHECK (model_family IN ('M1_INDICATOR_KRIGING', 'M2_ML', 'M3_HYBRID', 'BASELINE')),
    fold_id                 INTEGER REFERENCES spatial_folds (fold_id),
    status                  TEXT    NOT NULL CHECK (status IN ('DEFERRED', 'NOT_ESTIMABLE', 'FAILED', 'COMPLETED'))
);

CREATE TABLE model_predictions (
    prediction_id           INTEGER PRIMARY KEY,
    model_run_id            INTEGER NOT NULL REFERENCES model_runs (model_run_id),
    interval_key            TEXT    NOT NULL,
    p_raw                   REAL    CHECK (p_raw IS NULL OR (p_raw >= 0 AND p_raw <= 1)),
    p_calibrated            REAL    CHECK (p_calibrated IS NULL OR (p_calibrated >= 0 AND p_calibrated <= 1))
);

CREATE TABLE model_evaluation_metrics (
    metric_id               INTEGER PRIMARY KEY,
    model_run_id            INTEGER NOT NULL REFERENCES model_runs (model_run_id),
    metric_name             TEXT    NOT NULL,
    metric_value            REAL,
    metric_status           TEXT    NOT NULL CHECK (metric_status IN ('DEFERRED', 'UNDEFINED', 'COMPUTED'))
);

CREATE TABLE probability_calibration (
    calibration_id          INTEGER PRIMARY KEY,
    model_run_id            INTEGER NOT NULL REFERENCES model_runs (model_run_id),
    method                  TEXT    NOT NULL,
    fitted_on               TEXT    NOT NULL CHECK (fitted_on IN ('TRAINING_ONLY', 'INNER_HELD_OUT'))
);

CREATE TABLE uncertainty_voxels (
    voxel_id                INTEGER PRIMARY KEY,
    grid_version            TEXT    NOT NULL,
    x_m                     REAL    NOT NULL,
    y_m                     REAL    NOT NULL,
    z_relative_m            REAL    NOT NULL,
    probability             REAL    CHECK (probability IS NULL OR (probability >= 0 AND probability <= 1))
);

CREATE TABLE simulation_runs (
    simulation_run_id       INTEGER PRIMARY KEY,
    method                  TEXT    NOT NULL,
    n_realizations          INTEGER NOT NULL CHECK (n_realizations > 0),
    status                  TEXT    NOT NULL CHECK (status IN ('DEFERRED', 'SIS_NOT_SUPPORTED', 'COMPLETED'))
);

CREATE TRIGGER future_spatial_folds_blocked BEFORE INSERT ON spatial_folds
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_variogram_runs_blocked BEFORE INSERT ON variogram_runs
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_variogram_points_blocked BEFORE INSERT ON variogram_points
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_model_runs_blocked BEFORE INSERT ON model_runs
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_model_predictions_blocked BEFORE INSERT ON model_predictions
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_model_metrics_blocked BEFORE INSERT ON model_evaluation_metrics
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_calibration_blocked BEFORE INSERT ON probability_calibration
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_uncertainty_voxels_blocked BEFORE INSERT ON uncertainty_voxels
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;
CREATE TRIGGER future_simulation_runs_blocked BEFORE INSERT ON simulation_runs
BEGIN SELECT RAISE(ABORT, 'Stage B contract table: not populated in obj1_master'); END;

-- ===== 0008_views.sql =====
-- 0008_views.sql
-- Stable read-only views for figures, tables and downstream receipts.
-- Every view is restricted to the ACTIVE dataset version. Figure SQL reads these views only.
-- Rule identifiers used below are the Stage A candidate rules defined in config/label_rules.yaml:
--   STRICT_SGS_v1 (Target A: rock code Sgs), RECON_2OF3_v1 (Target B candidate: >= 2 of 3 indicators),
--   ALL3_v1 (all three indicators), ANY_v1 (any indicator). All are PROPOSED until a reviewer approves.

CREATE VIEW v_active_version AS
SELECT dataset_version_id, dataset_version_key, dataset_label, source_file_id, etl_version,
       rule_versions_json, coordinate_decision_json, created_utc, activated_utc
FROM dataset_versions
WHERE status = 'ACTIVE';

CREATE VIEW v_source_file AS
SELECT sf.source_file_id, sf.file_name, sf.original_path, sf.raw_copy_path, sf.sha256, sf.size_bytes
FROM source_files sf
WHERE sf.source_file_id = (SELECT source_file_id FROM v_active_version);

CREATE VIEW v_holes AS
SELECT h.hole_id, h.raw_hole_id, h.hole_type, h.grid_label, h.easting_alt_m, h.northing_alt_m,
       h.utm_easting_m, h.utm_northing_m, h.line_code, h.rl_status, h.rl_m, h.max_depth_m,
       h.project_code, h.prospect, h.contractor, h.logged_by, h.date_drilled, h.dataset_version_id
FROM holes h
WHERE h.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_drill_lines AS
SELECT dl.line_code, dl.nominal_northing_m, dl.n_holes, dl.n_intervals, dl.grouping_method, dl.status
FROM drill_lines dl
WHERE dl.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_survey AS
SELECT s.hole_id, s.depth_m, s.dip_deg, s.azimuth_deg, s.station_kind, s.surveyed_by, s.instrument,
       s.convention_status
FROM survey_stations s
WHERE s.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_intervals AS
SELECT li.interval_id, li.interval_key, li.hole_id, h.line_code, li.source_row,
       li.depth_from_m, li.depth_to_m, li.interval_length_m, li.midpoint_m,
       li.rock_code_raw, li.rock_code_status, li.rock_description,
       li.colour1_code, li.colour2_code, li.weathering_code, li.weathering_status,
       li.alt_min1_code, li.alt_min1_int, li.alt_min2_code, li.comment_raw, li.dataset_version_id
FROM logging_intervals li
JOIN holes h ON h.dataset_version_id = li.dataset_version_id AND h.hole_id = li.hole_id
WHERE li.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_label_evidence AS
SELECT i.interval_id, i.interval_key, i.hole_id, i.line_code, i.depth_from_m, i.depth_to_m,
       i.interval_length_m, i.midpoint_m, i.rock_code_raw, i.rock_code_status, i.weathering_code,
       i.weathering_status, i.comment_raw, i.alt_min1_code,
       e.is_sgs, e.has_gr_mineral, e.comment_present, e.comment_graphitic, e.comment_trace_qualified,
       e.comment_term, e.positive_indicators, e.negative_indicators, e.label_conflict,
       e.evidence_pattern, e.label_review_status, e.rationale
FROM interval_label_evidence e
JOIN v_intervals i ON i.interval_id = e.interval_id
WHERE e.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_label_candidates AS
SELECT l.rule_id, r.rule_family, r.status AS rule_status, r.rule_version, i.interval_id, i.interval_key,
       i.hole_id, i.line_code, i.interval_length_m, i.midpoint_m, i.weathering_code,
       l.label, l.label_state
FROM interval_labels l
JOIN graphite_label_rules r ON r.rule_id = l.rule_id
JOIN v_intervals i ON i.interval_id = l.interval_id
WHERE l.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_label_candidate_counts AS
SELECT rule_id, rule_family, rule_status, label_state,
       COUNT(*) AS n_intervals,
       ROUND(SUM(interval_length_m), 3) AS logged_m
FROM v_label_candidates
GROUP BY rule_id, rule_family, rule_status, label_state;

CREATE VIEW v_label_disagreement AS
SELECT evidence_pattern, label_review_status,
       COUNT(*) AS n_intervals,
       ROUND(SUM(interval_length_m), 3) AS logged_m
FROM v_label_evidence
GROUP BY evidence_pattern, label_review_status;

-- One row per interval with the candidate label states side by side (used by figures and tables).
CREATE VIEW v_interval_flags AS
SELECT e.interval_id, e.interval_key, e.hole_id, e.line_code, e.depth_from_m, e.depth_to_m,
       e.interval_length_m, e.midpoint_m, e.rock_code_raw, e.rock_code_status, e.weathering_code,
       e.weathering_status, e.comment_raw, e.is_sgs, e.has_gr_mineral, e.comment_graphitic,
       e.comment_trace_qualified, e.positive_indicators, e.negative_indicators, e.label_conflict,
       e.evidence_pattern, e.label_review_status,
       s.label_state  AS strict_state,
       r.label_state  AS recon_state,
       a3.label_state AS all3_state,
       an.label_state AS any_state
FROM v_label_evidence e
LEFT JOIN v_label_candidates s  ON s.interval_id = e.interval_id  AND s.rule_id  = 'STRICT_SGS_v1'
LEFT JOIN v_label_candidates r  ON r.interval_id = e.interval_id  AND r.rule_id  = 'RECON_2OF3_v1'
LEFT JOIN v_label_candidates a3 ON a3.interval_id = e.interval_id AND a3.rule_id = 'ALL3_v1'
LEFT JOIN v_label_candidates an ON an.interval_id = e.interval_id AND an.rule_id = 'ANY_v1';

CREATE VIEW v_hole_graphite AS
SELECT f.hole_id, f.line_code,
       COUNT(*) AS n_intervals,
       ROUND(SUM(f.interval_length_m), 3) AS logged_m,
       ROUND(SUM(CASE WHEN f.is_sgs = 1 THEN f.interval_length_m ELSE 0 END), 3) AS sgs_m,
       SUM(CASE WHEN f.is_sgs = 1 THEN 1 ELSE 0 END) AS sgs_n,
       ROUND(SUM(CASE WHEN f.has_gr_mineral = 1 THEN f.interval_length_m ELSE 0 END), 3) AS gr_mineral_m,
       ROUND(SUM(CASE WHEN f.comment_graphitic = 1 THEN f.interval_length_m ELSE 0 END), 3) AS comment_graphitic_m,
       ROUND(SUM(CASE WHEN f.comment_trace_qualified = 1 THEN f.interval_length_m ELSE 0 END), 3) AS comment_trace_m,
       ROUND(SUM(CASE WHEN f.recon_state = 'POSITIVE' THEN f.interval_length_m ELSE 0 END), 3) AS recon_pos_m,
       ROUND(SUM(CASE WHEN f.recon_state = 'UNRESOLVED' THEN f.interval_length_m ELSE 0 END), 3) AS recon_unresolved_m,
       SUM(CASE WHEN f.label_conflict = 1 THEN 1 ELSE 0 END) AS conflict_n,
       SUM(CASE WHEN f.rock_code_status <> 'VALID' THEN 1 ELSE 0 END) AS unresolved_code_n
FROM v_interval_flags f
GROUP BY f.hole_id, f.line_code;

CREATE VIEW v_line_graphite AS
SELECT f.line_code,
       COUNT(DISTINCT f.hole_id) AS n_holes,
       COUNT(*) AS n_intervals,
       ROUND(SUM(f.interval_length_m), 3) AS logged_m,
       ROUND(SUM(CASE WHEN f.is_sgs = 1 THEN f.interval_length_m ELSE 0 END), 3) AS sgs_m,
       SUM(CASE WHEN f.is_sgs = 1 THEN 1 ELSE 0 END) AS sgs_n,
       ROUND(SUM(CASE WHEN f.recon_state = 'POSITIVE' THEN f.interval_length_m ELSE 0 END), 3) AS recon_pos_m,
       ROUND(SUM(CASE WHEN f.recon_state = 'UNRESOLVED' THEN f.interval_length_m ELSE 0 END), 3) AS recon_unresolved_m,
       SUM(CASE WHEN f.label_conflict = 1 THEN 1 ELSE 0 END) AS conflict_n,
       SUM(CASE WHEN f.rock_code_status <> 'VALID' THEN 1 ELSE 0 END) AS unresolved_code_n
FROM v_interval_flags f
GROUP BY f.line_code;

CREATE VIEW v_depth_weathering AS
SELECT CAST(f.midpoint_m / 5 AS INTEGER) * 5 AS depth_bin_from_m,
       COALESCE(f.weathering_code, 'MISSING') AS weathering_class,
       COUNT(*) AS n_all,
       SUM(CASE WHEN f.strict_state = 'POSITIVE' THEN 1 ELSE 0 END) AS n_strict_positive,
       SUM(CASE WHEN f.strict_state = 'NEGATIVE' THEN 1 ELSE 0 END) AS n_strict_negative,
       SUM(CASE WHEN f.strict_state = 'UNRESOLVED' THEN 1 ELSE 0 END) AS n_strict_unresolved
FROM v_interval_flags f
GROUP BY depth_bin_from_m, weathering_class;

CREATE VIEW v_rock_code_usage AS
WITH dictionary AS (
    SELECT code, description
    FROM geological_code_dictionary
    WHERE code_domain = 'RockType'
      AND dataset_version_id = (SELECT dataset_version_id FROM v_active_version)
),
observed AS (
    SELECT rock_code_raw AS code, COUNT(*) AS n_intervals, SUM(interval_length_m) AS logged_m
    FROM v_intervals
    WHERE rock_code_raw IS NOT NULL
    GROUP BY rock_code_raw
)
SELECT d.code, d.description AS legend_description, 'VALID' AS code_status,
       COALESCE(o.n_intervals, 0) AS n_intervals, ROUND(COALESCE(o.logged_m, 0), 3) AS logged_m
FROM dictionary d
LEFT JOIN observed o ON o.code = d.code
UNION ALL
SELECT o.code, NULL, 'UNSUPPORTED', o.n_intervals, ROUND(o.logged_m, 3)
FROM observed o
WHERE o.code NOT IN (SELECT code FROM dictionary);

CREATE VIEW v_collar_plan AS
SELECT h.hole_id, h.line_code, h.utm_easting_m AS easting_m, h.utm_northing_m AS northing_m,
       h.easting_alt_m, h.northing_alt_m, h.max_depth_m,
       g.n_intervals, g.logged_m, g.sgs_m, g.sgs_n, g.recon_pos_m,
       CASE WHEN g.logged_m > 0 THEN ROUND(g.sgs_m / g.logged_m, 4) END AS sgs_fraction
FROM v_holes h
JOIN v_hole_graphite g ON g.hole_id = h.hole_id;

CREATE VIEW v_interval_geometry AS
SELECT gb.geometry_build_id, ic.interval_id, i.interval_key, i.hole_id, i.line_code,
       i.depth_from_m, i.depth_to_m, i.midpoint_m, i.rock_code_raw, i.rock_code_status,
       i.weathering_code, i.interval_length_m,
       ic.dip_deg, ic.azimuth_deg, ic.delta_e_m, ic.delta_n_m, ic.delta_z_m,
       ic.easting_m, ic.northing_m, ic.z_relative_m, ic.z_absolute_m, ic.z_reference,
       gb.geometry_status, f.strict_state, f.recon_state
FROM interval_coordinates ic
JOIN geometry_builds gb ON gb.geometry_build_id = ic.geometry_build_id
JOIN v_intervals i ON i.interval_id = ic.interval_id
JOIN v_interval_flags f ON f.interval_id = ic.interval_id
WHERE gb.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_qaqc_summary AS
SELECT f.check_id, c.category, c.description, f.severity, f.status, f.result,
       COUNT(*) AS n_findings,
       SUM(f.n_records) AS n_records
FROM qaqc_findings f
JOIN qaqc_checks c ON c.check_id = f.check_id
WHERE f.dataset_version_id = (SELECT dataset_version_id FROM v_active_version)
GROUP BY f.check_id, c.category, c.description, f.severity, f.status, f.result;

-- Non-blank counts for every raw field, computed from the stored JSON payload of each raw row.
CREATE VIEW v_completeness AS
WITH src AS (
    SELECT 'Collars' AS source_sheet, payload_json FROM raw_collars
    WHERE source_file_id = (SELECT source_file_id FROM v_active_version)
    UNION ALL
    SELECT 'Surveys', payload_json FROM raw_surveys
    WHERE source_file_id = (SELECT source_file_id FROM v_active_version)
    UNION ALL
    SELECT 'Logging', payload_json FROM raw_logging
    WHERE source_file_id = (SELECT source_file_id FROM v_active_version)
)
SELECT s.source_sheet, j.key AS field_name,
       COUNT(*) AS n_rows,
       SUM(CASE WHEN j.type = 'null' OR TRIM(j.value) = '' THEN 0 ELSE 1 END) AS n_non_blank
FROM src s, json_each(s.payload_json) j
GROUP BY s.source_sheet, j.key;

CREATE VIEW v_regional_context AS
SELECT r.regional_polygon_id, r.feature_index, r.geo_symbol, r.stratigraphy, r.legend_text,
       r.metamorphism, r.geom_wkt, r.centroid_e_m, r.centroid_n_m, r.scale_note
FROM regional_geology_context r
WHERE r.intersects_collar_buffer = 1;

CREATE VIEW v_export_receipts AS
SELECT r.receipt_id, r.canonical_dataset_id, r.source_workbook_sha256, r.label_rule_id, r.label_rule_status,
       r.geometry_build_id, r.crs_key, r.vertical_datum_status, r.export_name, r.selected_sql_sha256,
       r.row_count, r.ordered_id_digest, r.status, r.exported_utc
FROM dataset_export_receipts r
WHERE r.dataset_version_id = (SELECT dataset_version_id FROM v_active_version);

CREATE VIEW v_figure_manifest AS
SELECT m.figure_id, f.title, f.stage_status, m.output_format, m.output_path, m.output_sha256, m.output_bytes,
       m.exported_utc, q.sql_file, q.sql_sha256
FROM figure_export_manifest m
JOIN figure_registry f ON f.figure_id = m.figure_id
LEFT JOIN figure_query_registry q ON q.figure_query_id = m.figure_query_id;

